import { useState } from "react";

function useBoDem(start = 0) {
  const [dem, setDem] = useState(start);
  const tang = () => setDem((d) => d + 1);
  return { dem, tang };
}

function App() {
  const { dem, tang } = useBoDem();
  return <button onClick={tang}>Dem: {dem}</button>;
}

export default App;
